"""Every extracted invoice number, amount, and the threshold must appear in the collected data."""
import json
import re
from decimal import Decimal
from api import io


def amounts(text):
    return {Decimal(m.replace(',', '')) for m in re.findall(r'\$([0-9][0-9,]*\.?[0-9]*)', text) if m.replace(',', '').replace('.', '').isdigit()}


def handle(data):
    raw, out = data['inputs']['raw'], data['outputs']
    seen = amounts(raw)
    problems = []
    for inv in out['invoices']:
        if inv['invoice'] not in raw:
            problems.append(f"invoice {inv['invoice']} is not in the data")
        for key in ('amount_stated', 'amount'):
            value = Decimal(re.sub(r'[^0-9.]', '', inv[key]) or '0')
            if value not in seen:
                problems.append(f"{inv['invoice']} {key} {inv[key]} is not in the data")
    if Decimal(str(out['threshold_amount'])) not in seen:
        problems.append(f"threshold {out['threshold_amount']} is not in the data")
    return {'status': 'fail' if problems else 'pass', 'reason': '; '.join(problems) or 'Every invoice number, amount, and the threshold appear in the collected data.', 'evidence': []}


io(handle)

"""Read the sheet back: every confirmed row must be there once with its amount, and no rejected row may be there."""
from api import io, sheet_rows


def handle(data):
    rows = [' | '.join(map(str, r)) for r in sheet_rows('Pending Invoices')]
    problems = []
    for item in data['outputs']['confirmed']:
        copies = [r for r in rows if item['invoice'] in r]
        if not any(item['amount'] in r for r in copies):
            problems.append(f"{item['invoice']} is reported as written but is not in the sheet with {item['amount']}")
        elif len(copies) > 1:
            problems.append(f"{item['invoice']} is in the sheet {len(copies)} times")
    for item in data['outputs']['rejected']:
        if any(item['invoice'] in r for r in rows):
            problems.append(f"{item['invoice']} is reported as rejected but is in the sheet")
    return {'status': 'fail' if problems else 'pass',
            'reason': '; '.join(problems) or 'The sheet matches the confirmed and rejected rows.', 'evidence': []}


io(handle)

import base64
import copy
import json
import re
import sys
import time
from collections import Counter
from email.utils import getaddresses, parseaddr
from urllib.parse import quote

from app_tools import StopRun, call_tool, collect_names, total_amounts, tool_definitions


def unpack(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except (TypeError, ValueError):
            pass
    return value


def object_field(arguments, key):
    value = unpack(arguments.get(key))
    return copy.deepcopy(value) if isinstance(value, dict) else {}


def replace_text(value, marker, replacement):
    if isinstance(value, str):
        return value.replace(marker, replacement)
    if isinstance(value, list):
        return [replace_text(item, marker, replacement) for item in value]
    if isinstance(value, dict):
        return {key: replace_text(item, marker, replacement) for key, item in value.items()}
    return value


class Api:
    def __init__(self, state, seconds, ceiling):
        self.state = state
        self.deadline = time.monotonic() + seconds
        self.ceiling = ceiling

    def call(self, recipe, write=False):
        if self.state.get('stop'):
            raise StopRun('Service stopped; no further API calls are allowed')
        if time.monotonic() > self.deadline or self.state.get('api_calls', 0) >= self.ceiling:
            raise RuntimeError('Reserved execution budget reached; remaining actions are incomplete')
        if not isinstance(recipe, dict) or not recipe.get('name') or not isinstance(recipe.get('arguments'), dict):
            raise ValueError('Missing discovered API recipe')
        self.state['api_calls'] = self.state.get('api_calls', 0) + 1
        try:
            result = unpack(call_tool(recipe['name'], recipe['arguments'], 'write' if write else 'read'))
        except StopRun:
            self.state['stop'] = True
            raise
        if isinstance(result, dict) and (result.get('error') or result.get('ok') is False):
            raise RuntimeError(json.dumps(result, ensure_ascii=False))
        return result


def rows_from(result):
    if not isinstance(result, dict) or not isinstance(result.get('values', []), list):
        raise ValueError('Tracker did not return cell values')
    if 'values' not in result and 'range' not in result:
        raise ValueError('Tracker readback did not identify the requested range')
    return result.get('values', [])


def row_key(row):
    row = list(row)
    while row and row[-1] == '':
        row.pop()
    return tuple(row)


def header(message, name):
    for entry in message.get('payload', {}).get('headers', []):
        if entry.get('name', '').lower() == name.lower():
            return entry.get('value', '')
    return ''


def body_text(message):
    if isinstance(message.get('body_plain'), str):
        return message['body_plain']
    parts = []

    def walk(part):
        data = part.get('body', {}).get('data')
        if data and part.get('mimeType', 'text/plain') == 'text/plain':
            parts.append(base64.urlsafe_b64decode(data + '=' * (-len(data) % 4)).decode('utf-8'))
        for child in part.get('parts', []):
            walk(child)

    walk(message.get('payload', {}))
    return '\n'.join(parts)


def verify_mail(message, recipient, text, thread_id=''):
    if not isinstance(message, dict):
        raise ValueError('Sent message could not be read back')
    addresses = message.get('to') or header(message, 'To')
    addresses = addresses if isinstance(addresses, list) else [addresses]
    recipients = [address.lower() for _, address in getaddresses(addresses)]
    labels = message.get('labelIds', message.get('label_ids', []))
    if recipient.lower() not in recipients or 'SENT' not in labels:
        raise ValueError('Sent-message recipient or SENT state could not be verified')
    if body_text(message).replace('\r\n', '\n').rstrip('\n') != text.replace('\r\n', '\n').rstrip('\n'):
        raise ValueError('Sent-message body differs from the exact intended notification')
    actual_thread = message.get('threadId', message.get('thread_id'))
    if thread_id and actual_thread != thread_id:
        raise ValueError('Return email was not verified in the original thread')
    return {'id': message.get('id', message.get('message_id')), 'recipient': recipient,
            'body': text, 'sent': True, 'thread_id': actual_thread}


def encoded_value(value, text):
    candidates = [value] if isinstance(value, str) else []
    if isinstance(value, dict):
        candidates.extend(item for item in value.values() if isinstance(item, str))
    for candidate in candidates:
        try:
            decoded = base64.urlsafe_b64decode(candidate + '=' * (-len(candidate) % 4)).decode('utf-8')
            if decoded == text:
                return candidate.replace('+', '-').replace('/', '_').rstrip('=')
        except Exception:
            pass
    raise ValueError('Encoding tool did not return an exact base64 encoding of the notification')


def send_mail(api, mail, recipient, subject, text, thread_id='', message_id='', parts=None):
    if any('\r' in value or '\n' in value for value in (recipient, subject, message_id, thread_id)):
        raise ValueError('Unsafe newline in email header metadata; message not sent')
    if parseaddr(recipient)[1] != recipient or '@' not in recipient:
        raise ValueError('Return sender address is not a verified plain mailbox')
    headers = [{'name': 'From', 'value': 'ap@company.example.com'},
               {'name': 'To', 'value': recipient}, {'name': 'Subject', 'value': subject}]
    if message_id:
        headers.extend([{'name': 'In-Reply-To', 'value': message_id}, {'name': 'References', 'value': message_id}])
    recipe = copy.deepcopy(mail['send'])
    arguments = recipe['arguments']
    encoded_text = text
    if mail.get('format', 'payload') == 'raw':
        encoded_text = '\r\n'.join(entry['name'] + ': ' + entry['value'] for entry in headers)
        encoded_text += '\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Transfer-Encoding: 8bit\r\n\r\n' + text
    encoder = replace_text(mail['encode'], '__TEXT__', encoded_text)
    encoded = encoded_value(api.call(encoder), encoded_text)
    if mail.get('format', 'payload') == 'raw':
        if parts:
            raise ValueError('Required attachment parts cannot be dropped from a raw return')
        payload = {'raw': encoded}
    else:
        content = {'mimeType': 'text/plain', 'headers': headers, 'body': {'data': encoded}}
        if parts:
            content = {'mimeType': 'multipart/mixed', 'headers': headers,
                       'parts': [{'mimeType': 'text/plain', 'body': {'data': encoded}}] + parts}
        payload = {'payload': content}
    if thread_id:
        payload['threadId'] = thread_id
    arguments['body'] = json.dumps(payload, ensure_ascii=False)
    result = api.call(recipe, write=True)
    message_id_sent = result.get('id', result.get('message_id')) if isinstance(result, dict) else None
    if not message_id_sent:
        raise ValueError('Send completion is uncertain: no sent message ID. Do not resend blindly.')
    read = replace_text(mail['get'], '__MESSAGE_ID__', quote(message_id_sent, safe=''))
    try:
        return verify_mail(api.call(read), recipient, text, thread_id)
    except Exception as error:
        raise ValueError('Message ' + message_id_sent + ' was sent but readback is unverified: ' + str(error)) from error


def invoice_fields(invoice, columns):
    row = invoice['row']
    if not isinstance(row, list) or not row or not all(isinstance(cell, str) for cell in row):
        raise ValueError('Invoice row must contain only literal source strings')
    for field in ('vendor', 'invoice', 'date', 'amount', 'due_date'):
        if not isinstance(invoice.get(field), str) or not invoice[field]:
            raise ValueError('Missing required invoice field: ' + field)
        if row[columns[field]] != invoice[field]:
            raise ValueError('Row does not preserve planned ' + field)
    total_amounts([invoice['amount']])
    return row


def record(plan):
    state = {'plan': plan, 'logged': [], 'not_logged': [], 'returns': [], 'issues': list(plan.get('issues', [])),
             'api_calls': plan.get('read_calls', 0), 'stop': plan.get('stop', False), 'readback': []}
    if not plan.get('sources_complete'):
        state['issues'].append('The required source review was not completed.')
    api = Api(state, 105, 89)
    invoices = plan.get('invoices', [])
    sheet = plan.get('sheet', {})
    columns = sheet.get('columns', {})
    before = None
    attempts = []
    if any(invoice.get('disposition') == 'log' for invoice in invoices):
        try:
            before = rows_from(api.call(sheet['read']))
        except Exception as error:
            state['issues'].append('Tracker baseline read failed: ' + str(error))
    seen = set()
    for invoice in invoices:
        disposition = invoice.get('disposition')
        item = {'invoice': invoice.get('invoice', ''), 'reason': invoice.get('reason', ''),
                'vendor': invoice.get('vendor', ''), 'amount': invoice.get('amount', '')}
        if disposition != 'log':
            if disposition == 'hold' or disposition not in ('return', 'duplicate'):
                state['issues'].append('Invoice ' + item['invoice'] + ' is unresolved: ' + item['reason'])
            state['not_logged'].append(item)
            continue
        try:
            row = invoice_fields(invoice, columns)
            if before is None:
                raise ValueError('Not appended because the tracker could not be checked for duplicates')
            identity = (invoice['vendor'], invoice['invoice'])
            existing = any(len(saved) > max(columns['vendor'], columns['invoice']) and
                           (saved[columns['vendor']], saved[columns['invoice']]) == identity for saved in before)
            if existing or identity in seen:
                item['reason'] = 'Already present in the tracker or a duplicate submission; not logged again.'
                state['not_logged'].append(item)
                continue
            seen.add(identity)
            recipe = copy.deepcopy(sheet['append'])
            arguments = recipe['arguments']
            params = object_field(arguments, 'params')
            params.update({'valueInputOption': 'RAW', 'insertDataOption': 'INSERT_ROWS'})
            arguments['params'] = json.dumps(params)
            body = object_field(arguments, 'body')
            body.update({'majorDimension': 'ROWS', 'values': [row]})
            arguments['body'] = json.dumps(body, ensure_ascii=False)
            attempt = {'invoice': invoice, 'error': '', 'receipt': None}
            attempts.append(attempt)
            try:
                attempt['receipt'] = api.call(recipe, write=True)
            except Exception as error:
                attempt['error'] = str(error)
        except Exception as error:
            item['reason'] = 'Not logged: ' + str(error)
            state['not_logged'].append(item)
            state['issues'].append(invoice.get('invoice', '') + ': ' + str(error))
    if attempts:
        available = Counter()
        read_error = ''
        try:
            after = rows_from(api.call(sheet['read']))
            state['readback'] = after
            available = Counter(row_key(row) for row in after) - Counter(row_key(row) for row in before)
        except Exception as error:
            read_error = str(error)
            state['issues'].append('Tracker readback failed: ' + read_error)
        for attempt in attempts:
            invoice = attempt['invoice']
            identity = row_key(invoice['row'])
            if available[identity] > 0:
                available[identity] -= 1
                state['logged'].append({**invoice, 'receipt': attempt['receipt'], 'verified': True})
            else:
                reason = ('Not logged: the append failed and the row was absent from readback. ' + attempt['error']) if attempt['error'] and not read_error else (
                    'Not confirmed as logged: ' + (read_error or 'The exact intended row was absent from readback.'))
                state['not_logged'].append({'invoice': invoice['invoice'], 'vendor': invoice['vendor'],
                                            'amount': invoice['amount'], 'reason': reason})
                state['issues'].append(invoice['invoice'] + ': ' + reason)
    for invoice in invoices:
        if invoice.get('disposition') != 'return':
            continue
        try:
            sender = parseaddr(invoice['sender'])[1]
            if not sender or not invoice.get('return_text'):
                raise ValueError('Missing original sender or required return text')
            if invoice.get('prior_return_id'):
                recipe = replace_text(plan['mail']['get'], '__MESSAGE_ID__', quote(invoice['prior_return_id'], safe=''))
                receipt = verify_mail(api.call(recipe), sender, invoice['return_text'], invoice.get('thread_id', ''))
            else:
                subject = invoice.get('subject', '')
                subject = subject if subject.lower().startswith('re:') else 'Re: ' + subject
                receipt = send_mail(api, plan['mail'], sender, subject, invoice['return_text'],
                                    invoice.get('thread_id', ''), invoice.get('message_id_header', ''), invoice.get('return_parts'))
            state['returns'].append({'invoice': invoice['invoice'], 'receipt': receipt,
                                      'previously_sent': bool(invoice.get('prior_return_id'))})
        except Exception as error:
            reason = 'Vendor return incomplete for ' + invoice.get('invoice', '') + ': ' + str(error)
            state['issues'].append(reason)
            for item in state['not_logged']:
                if item['invoice'] == invoice.get('invoice') and item['vendor'] == invoice.get('vendor'):
                    item['reason'] += ' ' + reason
    return state


def recover_mail(api):
    names = collect_names(tool_definitions())
    search = next(name for name in names if name.endswith('api_search'))
    fetch = next(name for name in names if name.endswith('api_fetch'))
    encode = next(name for name in names if name.endswith('base64_encode'))
    result = api.call({'name': search, 'arguments': {'query': 'gmail messages send get', 'top_k': 20}})
    endpoints = result.get('results', [])
    send = next(item for item in endpoints if item.get('id', '').endswith('messages.send'))
    read = next(item for item in endpoints if item.get('id', '').endswith('messages.get'))
    def recipe(endpoint, message=False):
        url = endpoint['url'].replace('{userId}', 'ap@company.example.com').replace('{id}', '__MESSAGE_ID__')
        return {'name': fetch, 'arguments': {'method': endpoint['method'], 'url': url,
                                            'params': '{"format":"full"}' if message else None, 'body': None}}
    return {'send': recipe(send), 'get': recipe(read, True), 'format': 'payload',
            'encode': {'name': encode, 'arguments': {'text': '__TEXT__'}}}


def report_lines(state, total):
    plan = state['plan']
    date = plan.get('date')
    if not date:
        match = re.search(r'\b\d{4}-\d{2}-\d{2}\b', plan.get('instruction', ''))
        date = match.group() if match else 'requested morning'
    lines = ['AP processing for ' + date, '', 'Newly logged and verified in Invoice Tracker / Pending Invoices:']
    for invoice in state['logged']:
        lines.extend(['- ' + invoice['vendor'] + ' — ' + invoice['invoice'] + ' — ' + invoice['amount'],
                      '  Date: ' + invoice['date'] + '; Due date: ' + invoice['due_date']])
        if invoice.get('reason'):
            lines.append('  ' + invoice['reason'])
    if not state['logged']:
        lines.append('- None.')
    lines.extend(['', 'Not logged:'])
    for invoice in state['not_logged']:
        lines.append('- ' + invoice.get('vendor', '') + ' — ' + invoice['invoice'] +
                     (' — ' + invoice['amount'] if invoice.get('amount') else '') + ': ' + invoice['reason'])
    if not state['not_logged']:
        lines.append('- None.')
    lines.extend(['', 'Vendor returns:'])
    for returned in state['returns']:
        receipt = returned['receipt']
        lines.append('- ' + returned['invoice'] + ': ' + ('previously sent; verified' if returned['previously_sent'] else 'sent and verified') +
                     ' to ' + receipt['recipient'] + ' (message ' + str(receipt['id']) + ').')
    if not state['returns']:
        lines.append('- None confirmed this run.')
    if plan.get('policy_evidence'):
        lines.extend(['', 'Policy review: ' + plan['policy_evidence']])
    if state['issues']:
        lines.extend(['', 'Unresolved work:'] + ['- ' + issue for issue in state['issues']])
    lines.extend(['', 'Logged total: ' + total])
    return date, lines


def finish(state):
    api = Api(state, 42, 98)
    total = total_amounts([invoice['amount'] for invoice in state['logged']])['total']
    date, lines = report_lines(state, total)
    summary_status = 'incomplete' if state['issues'] else 'complete'
    body = '\n'.join(lines + ['', 'Status: ' + summary_status]) + '\n'
    receipt = None
    try:
        if state.get('stop'):
            raise StopRun('Service limit reached; no further API calls are allowed')
        mail = state['plan'].get('mail')
        if not mail or not all(mail.get(field) for field in ('send', 'get', 'encode')):
            mail = recover_mail(api)
        receipt = send_mail(api, mail, 'ap-lead@company.example.com',
                            'AP processing summary - ' + date + ' - ' + summary_status, body)
        lines.extend(['', 'Summary sent and verified to ap-lead@company.example.com (message ' + str(receipt['id']) + ').'])
    except Exception as error:
        state['issues'].append('Summary delivery incomplete: ' + str(error))
        lines.extend(['', 'Summary email to ap-lead@company.example.com was not confirmed sent: ' + str(error)])
    final = {'logged': [{'invoice': invoice['invoice'], 'amount': invoice['amount']} for invoice in state['logged']],
             'not_logged': [{'invoice': invoice['invoice'], 'reason': invoice['reason']} for invoice in state['not_logged']],
             'logged_total': total, 'status': 'incomplete' if state['issues'] or not receipt else 'complete'}
    lines.extend(['', 'Status: ' + final['status'], '', '```json', json.dumps(final, ensure_ascii=False), '```'])
    return {'report': '\n'.join(lines), 'completion': json.dumps({'final': final, 'summary': receipt,
                                                                'computed_total': total}, ensure_ascii=False)}


def check(inputs, mode):
    outputs = inputs.get('outputs', inputs)
    if mode == 'check_record':
        state = unpack(outputs['execution'])
        rows = Counter(row_key(row) for row in state['readback'])
        for invoice in state['logged']:
            if not invoice.get('verified') or rows[row_key(invoice['row'])] <= 0:
                raise ValueError('Logged claim lacks exact readback evidence')
        if any(not item['receipt'].get('sent') for item in state['returns']):
            raise ValueError('Return claim lacks sent-message evidence')
    else:
        completion = unpack(outputs['completion'])
        final = completion['final']
        if final['logged_total'] != total_amounts([item['amount'] for item in final['logged']])['total']:
            raise ValueError('Final total does not match actual verified rows')
        if completion['summary'] and 'Logged total: ' + final['logged_total'] not in completion['summary']['body'].splitlines():
            raise ValueError('Sent summary differs from final total')
        if not outputs['report'].endswith(json.dumps(final, ensure_ascii=False) + '\n```'):
            raise ValueError('Final report is missing the required JSON')
        if final['status'] == 'complete' and not completion['summary']:
            raise ValueError('Complete report lacks sent summary evidence')
    return {'status': 'pass', 'reason': 'Report reconciles with external readback evidence; any failures are explicitly incomplete.', 'evidence': []}


def main():
    mode = sys.argv[1]
    inputs = json.load(sys.stdin)
    if mode.startswith('check_'):
        try:
            result = check(inputs, mode)
        except Exception as error:
            result = {'status': 'fail', 'reason': str(error), 'evidence': []}
    elif mode == 'record':
        plan = unpack(inputs['plan'])
        result = {'execution': json.dumps(record(plan), ensure_ascii=False)}
    else:
        result = finish(unpack(inputs['execution']))
    print(json.dumps(result, ensure_ascii=False))


if __name__ == '__main__':
    main()

import asyncio
import base64
import copy
import json
import os
import re
import sys
import time
from collections import Counter
from email.header import Header
from email.utils import parseaddr
from pathlib import Path
from urllib.error import HTTPError

from ap_tools import amount_value, call_remote, extract_tools, read_only_call, sum_amounts, tool_definitions


ROOT = Path(__file__).parent
ARTIFACTS = Path(os.environ.get("METHOD_OUTPUT_DIR", "/tmp/ap-intake"))
ARTIFACTS.mkdir(parents=True, exist_ok=True)


def save(name, value):
    (ARTIFACTS / name).write_text(json.dumps(value, ensure_ascii=False), encoding="utf-8")


def unpack(value):
    for iteration in range(8):
        if isinstance(value, str):
            try:
                value = json.loads(value)
                continue
            except (ValueError, TypeError):
                return value
        if isinstance(value, dict):
            if "content" in value and isinstance(value["content"], list):
                texts = [entry.get("text", "") for entry in value["content"] if isinstance(entry, dict)]
                if len(texts) == 1:
                    value = texts[0]
                    continue
            if len(value) == 1 and "result" in value:
                value = value["result"]
                continue
        return value
    return value


def find_value(value, keys):
    value = unpack(value)
    if isinstance(value, dict):
        for key in keys:
            if key in value:
                return value[key]
        for item in value.values():
            if isinstance(item, (dict, list)):
                found = find_value(item, keys)
                if found is not None:
                    return found
    elif isinstance(value, list):
        for item in value:
            found = find_value(item, keys)
            if found is not None:
                return found
    return None


def decode_bodies(value):
    if isinstance(value, list):
        return [decode_bodies(item) for item in value]
    if not isinstance(value, dict):
        return value
    decoded = {key: decode_bodies(item) for key, item in value.items()}
    data = value.get("data")
    if isinstance(data, str) and re.fullmatch(r"[A-Za-z0-9_+/=-]+", data or " "):
        try:
            body = base64.urlsafe_b64decode(data + "=" * (-len(data) % 4)).decode("utf-8")
            if body and all(character.isprintable() or character in "\r\n\t" for character in body):
                decoded["_decoded"] = body
        except (ValueError, UnicodeError):
            pass
    return decoded


class AppSession:
    def __init__(self):
        try:
            self.names = {entry.get("function", entry).get("name") for entry in extract_tools(tool_definitions())}
        except (OSError, ValueError):
            self.names = set()
        self.stopped = False
        self.calls = 0
        self.trace = []

    def call(self, command, read_only=False):
        if self.stopped:
            return {"error": "HTTP 402: stopped; no further calls permitted"}
        name = command.get("name", "")
        arguments = command.get("arguments", {})
        if name not in self.names or not any(name.endswith(suffix) for suffix in ("api_search", "api_fetch", "base64_encode")):
            return {"error": "Unknown or disallowed tool name"}
        if read_only and not read_only_call(name, arguments):
            return {"error": "Research is read-only; use submit_plan for intended writes"}
        if self.calls >= 92:
            return {"error": "Reserved call budget reached"}
        self.calls += 1
        try:
            result = unpack(call_remote(name, arguments))
            if re.search(r'\b402\b', failure(result)):
                self.stopped = True
        except HTTPError as error:
            result = {"error": f"HTTP {error.code}: {error.read(4000).decode('utf-8', errors='replace')}"}
            if error.code == 402:
                self.stopped = True
        except Exception as error:
            result = {"error": f"{type(error).__name__}: {error}", "uncertain": True}
        self.trace.append({"call": command, "response": result})
        save("api-evidence.json", self.trace)
        return result


def failure(value):
    value = unpack(value)
    if not isinstance(value, dict):
        return ""
    if value.get("error") or value.get("isError") or value.get("success") is False:
        return json.dumps(value, ensure_ascii=False)
    for key in ("status", "status_code", "statusCode"):
        status = value.get(key)
        if isinstance(status, int) and status >= 400:
            return json.dumps(value, ensure_ascii=False)
    for key in ("body", "data", "response", "result"):
        if key in value:
            nested = failure(value[key])
            if nested:
                return nested
    return ""


def substitute(value, replacements):
    if isinstance(value, str):
        if value in replacements:
            return copy.deepcopy(replacements[value])
        if value.lstrip().startswith(("{", "[")):
            try:
                return json.dumps(substitute(json.loads(value), replacements), ensure_ascii=False)
            except ValueError:
                pass
        for key, replacement in replacements.items():
            if isinstance(replacement, str):
                value = value.replace(key, replacement)
        return value
    if isinstance(value, dict):
        return {key: substitute(item, replacements) for key, item in value.items()}
    if isinstance(value, list):
        return [substitute(item, replacements) for item in value]
    return value


def rows_from(response):
    if failure(response):
        return None
    rows = find_value(response, ("values",))
    if rows is None and isinstance(response, dict) and not failure(response):
        if find_value(response, ("range",)):
            return []
    return rows if isinstance(rows, list) and all(isinstance(row, list) for row in rows) else None


def normalized_row(row):
    result = [str(value) for value in row]
    while result and result[-1] == "":
        result.pop()
    return tuple(result)


def prepare_empty(instruction):
    match = re.search(r"\b\d{4}-\d{2}-\d{2}\b", instruction)
    return {"date": match.group() if match else "requested morning", "research_complete": False,
            "issues": [], "invoices": [], "mail": {}}


async def investigate(instruction):
    from openai import AsyncOpenAI

    plan = prepare_empty(instruction)
    session = AppSession()
    definitions = tool_definitions()
    tools = [
        {"type": "function", "name": "read_batch", "strict": False, "description": "Run independent documented simulated API searches or GET reads. Never writes. Arguments use the original tool definitions supplied in the prompt.",
         "parameters": {"type": "object", "properties": {"calls": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "arguments": {"type": "object", "additionalProperties": True}}, "required": ["name", "arguments"]}}}, "required": ["calls"]}},
        {"type": "function", "name": "checkpoint_plan", "strict": False, "description": "Persist a partial plan so interruption still produces an honest report. Does not finish research.",
         "parameters": {"type": "object", "properties": {"plan": {"type": "object", "additionalProperties": True}}, "required": ["plan"]}},
        {"type": "function", "name": "submit_plan", "strict": False, "description": "Finish research and hand the plan to deterministic invoice logging and reporting. This is the required final action.",
         "parameters": {"type": "object", "properties": {"plan": {"type": "object", "additionalProperties": True}}, "required": ["plan"]}}
    ]
    conversation = [{"role": "system", "content": (ROOT / "ap_prompt.txt").read_text()},
                    {"role": "user", "content": instruction + "\n\nOriginal simulated tool definitions:\n" + json.dumps(definitions)}]
    client = AsyncOpenAI(base_url=os.environ["TASK_MODEL_API_BASE"], api_key=os.environ["TASK_MODEL_API_KEY"], max_retries=0, timeout=80)
    started = time.monotonic()
    try:
        for turn in range(18):
            remaining = 305 - (time.monotonic() - started)
            if remaining < 15 or session.stopped:
                break
            if turn >= 12 or remaining < 80 or session.calls >= 52:
                conversation.append({"role": "user", "content": "Research budget is nearly exhausted. Submit the best fully evidenced plan NOW, preserving mail templates and every discovered invoice; disclose any missing evidence. No redundant investigation."})
            response = await asyncio.wait_for(client.responses.create(
                model=os.environ["TASK_MODEL_NAME"], input=conversation, tools=tools,
                store=False, include=["reasoning.encrypted_content"]), timeout=min(remaining, 80))
            conversation.extend(item.model_dump(exclude_none=True) for item in response.output)
            save("model-conversation.json", conversation)
            calls = [item for item in response.output if item.type == "function_call"]
            if not calls:
                conversation.append({"role": "user", "content": "Return the structured plan with submit_plan; do not provide a prose final answer."})
                continue
            finished = False
            for call in calls:
                try:
                    arguments = json.loads(call.arguments)
                    if call.name in ("checkpoint_plan", "submit_plan"):
                        candidate = arguments["plan"]
                        if not isinstance(candidate.get("invoices", []), list):
                            raise ValueError("invoices must be a list")
                        plan.update(candidate)
                        save("prepared-checkpoint.json", plan)
                        result = {"saved": True}
                        finished = finished or call.name == "submit_plan"
                    else:
                        commands = arguments["calls"]
                        if not 1 <= len(commands) <= 20:
                            raise ValueError("Use 1-20 calls per batch")
                        if session.calls + len(commands) > 58:
                            raise ValueError("Research call budget reached. Submit the plan now; reserve calls for logging and email.")
                        results = await asyncio.gather(*(asyncio.to_thread(session.call, command, True) for command in commands))
                        result = [{"call": command, "result": decode_bodies(output)} for command, output in zip(commands, results)]
                except Exception as error:
                    result = {"error": str(error)}
                conversation.append({"type": "function_call_output", "call_id": call.call_id, "output": json.dumps(result, ensure_ascii=False)})
            save("model-conversation.json", conversation)
            if finished:
                plan["remote_calls"] = session.calls
                plan["stopped"] = session.stopped
                return plan
        plan["issues"].append("Research limit reached before final submission; intake may be incomplete.")
    except Exception as error:
        if getattr(error, "status_code", None) == 402:
            session.stopped = True
        plan["issues"].append(f"Research interrupted: {type(error).__name__}: {error}")
    finally:
        await client.close()
    plan["research_complete"] = False
    plan["stopped"] = session.stopped
    plan["remote_calls"] = session.calls
    return plan


def encoded_value(response):
    response = unpack(response)
    if isinstance(response, str):
        candidate = response.strip()
        if re.fullmatch(r"[A-Za-z0-9+/=_-]+", candidate):
            return candidate
    candidate = find_value(response, ("encoded", "base64", "encoded_data", "encodedData", "base64_encoded", "encoded_text", "data", "result"))
    if candidate is not None and candidate != response:
        return encoded_value(candidate)
    raise ValueError("No base64 string in encoding tool response")


def send_email(session, mail, recipient, subject, body):
    if session.stopped:
        return {"sent": False, "error": "HTTP 402: stopped"}
    if not mail.get("encode") or not mail.get("send"):
        return {"sent": False, "error": "Email API templates unavailable"}
    address = parseaddr(recipient)[1]
    if not address or "@" not in address or any(character in recipient for character in "\r\n"):
        return {"sent": False, "error": "Invalid original sender address"}
    mime = "\r\n".join(["From: ap@company.example.com", "To: " + address,
                            "Subject: " + Header(subject, "utf-8").encode(), "MIME-Version: 1.0",
                            'Content-Type: text/plain; charset="utf-8"', "Content-Transfer-Encoding: 8bit", "", body])
    try:
        encoded = session.call(substitute(mail["encode"], {"__MIME__": mime}))
        if failure(encoded):
            raise ValueError(failure(encoded))
        raw = encoded_value(encoded).replace("+", "-").replace("/", "_").rstrip("=")
        response = session.call(substitute(mail["send"], {"__RAW__": raw}))
        if failure(response):
            return {"sent": False, "error": failure(response), "response": response}
        message_id = find_value(response, ("id", "messageId", "message_id"))
        if not message_id:
            return {"sent": False, "error": "Send completion uncertain: no message receipt; not retried", "response": response}
        return {"sent": True, "id": message_id, "to": address, "body": body, "response": response}
    except Exception as error:
        return {"sent": False, "error": f"{type(error).__name__}: {error}"}


def apply_plan(plan):
    ledger = {"plan": plan, "logged": [], "not_logged": [], "returns": [],
              "issues": list(plan.get("issues", [])), "readback": None, "stopped": plan.get("stopped", False)}
    session = AppSession()
    session.stopped = ledger["stopped"]
    session.calls = plan.get("remote_calls", 0)
    candidates = plan.get("invoices", [])
    attempted = []
    scheduled = set()
    started = time.monotonic()
    before = None
    try:
        if plan.get("research_complete") and plan.get("sheet_read"):
            before = rows_from(session.call(plan["sheet_read"], read_only=True))
        for invoice in candidates:
            decision = invoice.get("decision", "hold")
            reason = invoice.get("reason", "")
            if not plan.get("research_complete"):
                reason = "Not processed: required policy/source research is incomplete"
            elif decision == "log":
                if time.monotonic() - started > 90:
                    reason = "Not logged: execution time reserved for reconciliation and summary"
                elif before is None:
                    reason = "Not logged: could not read current Pending Invoices rows"
                elif not plan.get("append"):
                    reason = "Not logged: append API unavailable"
                else:
                    row = invoice.get("row", [])
                    required = [invoice.get(field) for field in ("vendor", "invoice", "date", "amount", "due_date")]
                    if not row or not all(isinstance(value, str) for value in row) or not all(isinstance(value, str) and value in row and value for value in required):
                        reason = "Not logged: exact required source values are missing from the prepared row"
                    elif (invoice["vendor"], invoice["invoice"]) in scheduled:
                        reason = "Duplicate incoming copy; the same vendor/invoice was already attempted this run"
                        decision = "duplicate"
                    elif any(invoice["invoice"] in existing and invoice["vendor"] in existing for existing in before):
                        reason = "Already present in Pending Invoices; not newly logged"
                        decision = "duplicate"
                    else:
                        try:
                            amount_value(invoice["amount"])
                        except ValueError as error:
                            reason = "Not logged: " + str(error)
                            ledger["not_logged"].append({"invoice": invoice["invoice"], "reason": reason})
                            ledger["issues"].append(invoice["invoice"] + ": " + reason)
                            continue
                        response = session.call(substitute(plan["append"], {"__ROW__": row}))
                        scheduled.add((invoice["vendor"], invoice["invoice"]))
                        attempted.append({"invoice": invoice, "response": response})
                        save("invoice-checkpoint.json", {"ledger": ledger, "attempted": attempted})
                        continue
            if not reason:
                reason = "Blocked vendor" if decision == "blocked" else "Held for AP review"
            ledger["not_logged"].append({"invoice": invoice.get("invoice", "unidentified"), "reason": reason})
            if decision == "hold" or not plan.get("research_complete") or (decision == "log" and reason):
                ledger["issues"].append(reason + ": " + invoice.get("invoice", "unidentified"))
        if attempted:
            ledger["readback"] = session.call(plan["sheet_read"], read_only=True)
            after_rows = rows_from(ledger["readback"])
            new_rows = Counter(normalized_row(row) for row in (after_rows or [])) - Counter(normalized_row(row) for row in (before or []))
            for attempt in attempted:
                invoice = attempt["invoice"]
                key = normalized_row(invoice["row"])
                if after_rows is not None and new_rows[key] > 0:
                    new_rows[key] -= 1
                    ledger["logged"].append(invoice)
                else:
                    error = failure(attempt["response"])
                    reason = "Sheet rejected invoice: " + error if error else "Append not confirmed by sheet readback; not retried"
                    ledger["not_logged"].append({"invoice": invoice["invoice"], "reason": reason})
                    ledger["issues"].append(invoice["invoice"] + ": " + reason)
        save("invoice-checkpoint.json", ledger)
        for invoice in candidates:
            if invoice.get("decision") != "blocked" or not plan.get("research_complete"):
                continue
            if invoice.get("return_already_sent") and invoice.get("return_receipt"):
                result = {"sent": True, "id": invoice["return_receipt"], "existing": True, "to": invoice.get("sender", "")}
            elif time.monotonic() - started > 110:
                result = {"sent": False, "error": "Execution time reserved for AP summary and final report"}
            else:
                body = invoice.get("return_body") or ("We cannot process this invoice under our current AP guidelines.\n"
                        + f"Vendor: {invoice.get('vendor', '')}\nInvoice: {invoice.get('invoice', '')}\nAmount: {invoice.get('amount', '')}")
                result = send_email(session, plan.get("mail", {}), invoice.get("sender", ""), "Invoice returned — AP processing", body)
            ledger["returns"].append({"invoice": invoice["invoice"], **result})
            if not result["sent"]:
                ledger["issues"].append("Blocked return not sent for " + invoice["invoice"] + ": " + result.get("error", "unknown error"))
            save("invoice-checkpoint.json", ledger)
    except Exception as error:
        ledger["issues"].append(f"Processing interrupted: {type(error).__name__}: {error}")
    accounted = {item["invoice"] for item in ledger["logged"] + ledger["not_logged"]}
    for invoice in candidates:
        if invoice.get("invoice") not in accounted:
            ledger["not_logged"].append({"invoice": invoice.get("invoice", "unidentified"), "reason": "Processing interrupted; logging not confirmed"})
    ledger["stopped"] = session.stopped
    ledger["remote_calls"] = session.calls
    return ledger


def make_report(ledger):
    plan = ledger["plan"]
    session = AppSession()
    session.stopped = ledger.get("stopped", False)
    session.calls = ledger.get("remote_calls", 0)
    amounts = [invoice["amount"] for invoice in ledger["logged"]]
    total_data = sum_amounts({"amounts": amounts})
    total = "$" + format(amount_value(total_data["total"]), f",.{len(total_data['total'].partition('.')[2])}f")
    lines = ["AP invoice intake — " + plan.get("date", "requested morning"), "", "Logged:"]
    for invoice in ledger["logged"]:
        lines.append(f"- {invoice['invoice']} | {invoice['vendor']} | Date: {invoice['date']} | Amount: {invoice['amount']} | Due: {invoice['due_date']}")
        extras = [value for value in invoice.get("row", []) if value and value not in [invoice.get(field) for field in ("vendor", "invoice", "date", "amount", "due_date")]]
        if extras:
            lines.append("  " + " | ".join(extras))
    if not ledger["logged"]:
        lines.append("- None confirmed newly logged.")
    lines.extend(["", "Not logged:"])
    for invoice in ledger["not_logged"]:
        lines.append("- " + invoice["invoice"] + ": " + invoice["reason"])
    if not ledger["not_logged"]:
        lines.append("- None.")
    for receipt in ledger["returns"]:
        lines.append("- Return " + ("sent" if receipt["sent"] else "NOT sent") + " for " + receipt["invoice"] + (" to " + receipt["to"] if receipt.get("to") else ""))
    lines.extend(["", "Logged total: " + total])
    if ledger["issues"]:
        lines.extend(["", "Unfinished work:", *["- " + issue for issue in dict.fromkeys(ledger["issues"])]] )
    body = "\n".join(lines)
    receipt = send_email(session, plan.get("mail", {}), "ap-lead@company.example.com", "AP invoice intake — " + plan.get("date", "morning"), body)
    save("summary-receipt.json", receipt)
    complete = bool(plan.get("research_complete")) and not ledger["issues"] and receipt["sent"]
    summary = "Summary sent to ap-lead@company.example.com." if receipt["sent"] else "Summary NOT sent: " + receipt.get("error", "completion uncertain")
    final = {"logged": [{"invoice": invoice["invoice"], "amount": invoice["amount"]} for invoice in ledger["logged"]],
             "not_logged": ledger["not_logged"], "logged_total": total, "status": "complete" if complete else "incomplete"}
    return {"report": body + "\n\n" + summary + "\nStatus: " + final["status"] + "\n\n```json\n" + json.dumps(final, ensure_ascii=False) + "\n```", "delivery": json.dumps(receipt, ensure_ascii=False)}


def main():
    request = json.load(sys.stdin)
    mode = sys.argv[1]
    if mode == "prepare":
        try:
            plan = asyncio.run(investigate(request["instruction"]))
        except Exception as error:
            plan = prepare_empty(request["instruction"])
            plan["issues"].append(f"Research unavailable: {type(error).__name__}: {error}")
        output = {"prepared": json.dumps(plan, ensure_ascii=False)}
    elif mode == "apply":
        output = {"ledger": json.dumps(apply_plan(json.loads(request["prepared"])), ensure_ascii=False)}
    elif mode == "report":
        output = make_report(json.loads(request["ledger"]))
    elif mode == "check_rows":
        ledger = json.loads(request["outputs"]["ledger"])
        observed = Counter(normalized_row(row) for row in (rows_from(ledger.get("readback")) or []))
        claims = Counter(normalized_row(invoice["row"]) for invoice in ledger["logged"])
        valid = all(observed[row] >= count for row, count in claims.items())
        output = {"status": "pass" if valid else "fail", "reason": "Logged outcomes reconciled with actual sheet readback; failures are disclosed.", "evidence": [invoice["invoice"] for invoice in ledger["logged"]]}
    elif mode == "check_mail":
        receipt = json.loads(request["outputs"]["delivery"])
        valid = not receipt["sent"] or bool(receipt.get("id") and not failure(receipt.get("response", {})))
        output = {"status": "pass" if valid else "fail", "reason": "Summary delivery claim is supported by the send receipt, or explicitly reported as failed.", "evidence": [str(receipt.get("id", receipt.get("error", "unknown")))]}
    else:
        raise ValueError("Unknown execution mode")
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    main()

import json
import sys

from ap_agent import obvious_failure, total_amount, verify_logged_record


def check(payload):
    outputs = payload.get("outputs", payload)
    audit = json.loads(outputs["audit"])
    records = audit["records"]
    if "$" + total_amount(records) != audit["total"]:
        raise ValueError("Reported total differs from the confirmed logged ledger")
    refs = list(audit["summary_send_refs"])
    for record in records:
        if record["outcome"] == "logged":
            if not record["write_refs"] or not record["verify_refs"]:
                raise ValueError("Logged invoice lacks write/readback evidence")
            refs.extend(record["write_refs"] + record["verify_refs"])
            verify_logged_record(record, audit["calls"])
        elif record["outcome"] in ("returned", "already_returned"):
            evidence = record["write_refs"] or record["verify_refs"]
            if not evidence:
                raise ValueError("Returned invoice lacks send evidence")
            refs.extend(evidence)
    for reference in refs:
        call = audit["calls"].get(reference)
        if not call or not call["name"].endswith("api_fetch") or obvious_failure(call["result"]):
            raise ValueError("Claimed external action lacks successful API evidence")
    if audit["status"] == "complete" and (not audit["summary_send_refs"] or any(record["outcome"] in ("pending", "failed") for record in records)):
        raise ValueError("Incomplete work was labeled complete")
    return {"status": "pass", "reason": "Reported outcomes reconcile with recorded API evidence and exact amounts.", "evidence": ["Logged total: " + audit["total"], "Reported status: " + audit["status"]] + refs}


