import base64
import json
import os
import re
import sys
from decimal import Decimal
from email import policy
from email.parser import BytesParser
from urllib.parse import unquote

from sim_api import exact_sum


def parsed(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except ValueError:
            return value
    return value


def rows(value):
    if not isinstance(value, dict):
        return []
    found = value.get('values', [])
    for child in value.get('valueRanges', []):
        if 'Pending Invoices' in child.get('range', ''):
            found = found + child.get('values', [])
    return found


def message_body(message):
    if message.get('raw'):
        encoded = message['raw']
        decoded = base64.urlsafe_b64decode(encoded + '=' * (-len(encoded) % 4))
        email = BytesParser(policy=policy.default).parsebytes(decoded)
        part = email.get_body(preferencelist=('plain',)) if email.is_multipart() else email
        return part.get_content() if part else ''
    if message.get('body_plain') is not None:
        return message['body_plain']
    payload = message.get('payload', message)
    encoded = payload.get('body', {}).get('data')
    if encoded:
        return base64.urlsafe_b64decode(encoded + '=' * (-len(encoded) % 4)).decode('utf-8')
    return '\n'.join(message_body({'payload': part}) for part in payload.get('parts', []))


def recipients(message):
    if message.get('raw'):
        encoded = message['raw']
        decoded = base64.urlsafe_b64decode(encoded + '=' * (-len(encoded) % 4))
        return str(BytesParser(policy=policy.default).parsebytes(decoded).get('To', ''))
    destination = message.get('to', [])
    if isinstance(destination, str):
        destination = [destination]
    else:
        destination = list(destination)
    for header in message.get('payload', {}).get('headers', []):
        if header.get('name', '').lower() == 'to':
            destination.append(header.get('value', ''))
    return ','.join(destination)


def check(inputs):
    report = inputs['outputs']['report']
    matches = list(re.finditer(r'[{]\s*"logged"\s*:', report))
    if not matches:
        raise ValueError('Final report has no disposition JSON')
    disposition, end = json.JSONDecoder().raw_decode(report[matches[-1].start():])
    incomplete = disposition.get('status') == 'incomplete'
    path = os.path.join(os.environ['METHOD_OUTPUT_DIR'], 'api-journal.jsonl')
    if not os.path.exists(path):
        if incomplete and not disposition.get('logged'):
            return 'Incomplete report; no external changes claimed.', []
        raise ValueError('No API evidence available')
    with open(path, encoding='utf-8') as journal:
        events = [json.loads(line) for line in journal if line.strip()]
    confirmed_rows = []
    sent = []
    evidence = []
    uncertain = []
    for index, event in enumerate(events):
        if event['name'] != 'api_fetch':
            continue
        arguments = event['arguments']
        url = unquote(arguments.get('url', ''))
        if arguments.get('method', 'GET').upper() != 'POST':
            continue
        result = parsed(event['result'])
        if not isinstance(result, dict) or result.get('error'):
            continue
        body = parsed(arguments.get('body', '{}'))
        later = [item for item in events[index + 1:] if item['name'] == 'api_fetch' and item['arguments'].get('method', 'GET').upper() == 'GET']
        if '/spreadsheets/' in url and ':append' in url:
            prefix = url.split('/values')[0]
            actual = []
            for read in later:
                if unquote(read['arguments'].get('url', '')).startswith(prefix + '/values'):
                    actual.extend(rows(parsed(read['result'])))
            for intended in body.get('values', []):
                normalized = [str(cell) for cell in intended]
                while normalized and normalized[-1] == '':
                    normalized.pop()
                if any([str(cell) for cell in row[:len(normalized)]] == normalized for row in actual):
                    confirmed_rows.append([str(cell) for cell in intended])
                else:
                    uncertain.append('Spreadsheet row lacks matching readback')
            evidence.append('Compared append rows against subsequent spreadsheet reads.')
        elif url.endswith('/messages/send'):
            message_id = result.get('id')
            verified = None
            for read in later:
                observed = parsed(read['result'])
                if isinstance(observed, dict) and observed.get('id') == message_id:
                    verified = observed
                    break
            if verified:
                expected_body = message_body(body) if isinstance(body, dict) and ('payload' in body or 'raw' in body) else None
                if expected_body is not None and message_body(verified).replace('\r\n', '\n') != expected_body.replace('\r\n', '\n'):
                    raise ValueError('Sent email body differs from intended content')
                expected_to = recipients(body) if isinstance(body, dict) else ''
                if expected_to and expected_to not in recipients(verified):
                    raise ValueError('Sent email recipient differs from intended recipient')
                sent.append(verified)
                evidence.append('Verified sent message ' + str(message_id))
            else:
                uncertain.append('Sent message lacks independent readback: ' + str(message_id))
    for logged in disposition.get('logged', []):
        if not any(logged['invoice'] in row and logged['amount'] in row for row in confirmed_rows):
            raise ValueError('Reported logged invoice has no confirmed appended row: ' + logged['invoice'])
    total = exact_sum([item['amount'] for item in disposition.get('logged', [])])['total']
    reported_total = str(disposition.get('logged_total', '')).replace('$', '').replace(',', '').strip()
    if Decimal(total) != Decimal(reported_total):
        raise ValueError('Reported total differs from exact sum of logged amounts')
    summaries = [message for message in sent if 'ap-lead@company.example.com' in recipients(message)]
    expected_line = 'Logged total: ' + disposition['logged_total']
    if summaries and expected_line not in message_body(summaries[-1]).splitlines():
        raise ValueError('Summary total line differs from final report')
    if not incomplete and (uncertain or not summaries):
        raise ValueError('; '.join(uncertain) or 'No independently verified sent summary')
    return 'External-change claims match recorded independent readbacks.' + (' Incomplete work remains explicitly reported.' if incomplete else ''), evidence


def main():
    try:
        reason, evidence = check(json.load(sys.stdin))
        output = {'status': 'pass', 'reason': reason, 'evidence': evidence}
    except Exception as error:
        output = {'status': 'fail', 'reason': str(error), 'evidence': []}
    print(json.dumps(output))


if __name__ == '__main__':
    main()

